1	import { Router } from "express";
2	import { and, desc, eq, gte, isNull, sql } from "drizzle-orm";
3	import type { Db } from "@paperclipai/db";
4	import {
5	  activityLog,
6	  agents,
7	  authUsers,
8	  companyMemberships,
9	  costEvents,
10	  issueComments,
11	  issues,
12	} from "@paperclipai/db";
13	import type {
14	  UserProfileDailyPoint,
15	  UserProfileIdentity,
16	  UserProfileResponse,
17	  UserProfileWindowStats,
18	} from "@paperclipai/shared";
19	import { notFound } from "../errors.js";
20	import { assertCompanyAccess } from "./authz.js";
