22	type CompanyUserRow = {
23	  id: string;
24	  principalId: string;
25	  status: string;
26	  membershipRole: string | null;
27	  createdAt: Date;
28	  userId: string | null;
29	  name: string | null;
30	  email: string | null;
31	  image: string | null;
32	};
33	
34	const PROFILE_WINDOWS = [
35	  { key: "last7", label: "Last 7 days", days: 7 },
36	  { key: "last30", label: "Last 30 days", days: 30 },
37	  { key: "all", label: "All time", days: null },
38	] as const;
