63	async function resolveCompanyUser(db: Db, companyId: string, rawSlug: string): Promise<CompanyUserRow | null> {
64	  const slug = slugifyUserPart(rawSlug);
65	  if (!slug) return null;
66	
67	  const rows = await db
68	    .select({
69	      id: companyMemberships.id,
70	      principalId: companyMemberships.principalId,
71	      status: companyMemberships.status,
72	      membershipRole: companyMemberships.membershipRole,
73	      createdAt: companyMemberships.createdAt,
74	      userId: authUsers.id,
75	      name: authUsers.name,
76	      email: authUsers.email,
77	      image: authUsers.image,
78	    })
79	    .from(companyMemberships)
80	    .leftJoin(authUsers, eq(authUsers.id, companyMemberships.principalId))
81	    .where(
82	      and(
83	        eq(companyMemberships.companyId, companyId),
84	        eq(companyMemberships.principalType, "user"),
85	      ),
86	    )
87	    .orderBy(desc(companyMemberships.updatedAt))
88	    .limit(200);
89	
90	  return rows.find((row) => userSlugCandidates(row).includes(slug)) ?? null;
91	}
