93	function userIssueInvolvementSql(companyId: string, userId: string) {
94	  return sql<boolean>`
95	    (
96	      ${issues.createdByUserId} = ${userId}
97	      OR ${issues.assigneeUserId} = ${userId}
98	      OR EXISTS (
99	        SELECT 1
100	        FROM ${issueComments}
101	        WHERE ${issueComments.companyId} = ${companyId}
102	          AND ${issueComments.issueId} = ${issues.id}
103	          AND ${issueComments.authorUserId} = ${userId}
104	      )
105	    )
106	  `;
107	}
108	
109	function windowStart(days: number | null) {
110	  if (!days) return null;
111	  return new Date(Date.now() - days * 24 * 60 * 60 * 1000);
112	}
113	
114	function startOfUtcDay(date: Date) {
115	  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
116	}
117	
118	function isoDay(date: Date) {
119	  return startOfUtcDay(date).toISOString().slice(0, 10);
120	}
121	
122	function dayKeyExpr(dateSql: ReturnType<typeof sql>) {
123	  return sql<string>`to_char(date_trunc('day', ${dateSql}), 'YYYY-MM-DD')`;
124	}
125	
126	function sumNumber(column: typeof costEvents.costCents | typeof costEvents.inputTokens | typeof costEvents.cachedInputTokens | typeof costEvents.outputTokens) {
127	  return sql<number>`coalesce(sum(${column}), 0)::double precision`;
128	}
