130	async function loadWindowStats(
131	  db: Db,
132	  companyId: string,
133	  userId: string,
134	  key: UserProfileWindowStats["key"],
135	  label: string,
136	  from: Date | null,
137	): Promise<UserProfileWindowStats> {
138	  const involvement = userIssueInvolvementSql(companyId, userId);
139	  const openStatuses = ["backlog", "todo", "in_progress", "in_review", "blocked"];
140	  const fromIso = from?.toISOString();
141	
142	  const [issueStats] = await db
143	    .select({
144	      touchedIssues: sql<number>`count(distinct case when ${involvement} ${fromIso ? sql`and ${issues.updatedAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
145	      createdIssues: sql<number>`count(distinct case when ${issues.createdByUserId} = ${userId} ${fromIso ? sql`and ${issues.createdAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
146	      completedIssues: sql<number>`count(distinct case when ${involvement} and ${issues.status} = 'done' ${fromIso ? sql`and ${issues.completedAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
147	      assignedOpenIssues: sql<number>`count(distinct case when ${issues.assigneeUserId} = ${userId} and ${issues.status} in (${sql.join(openStatuses.map((status) => sql`${status}`), sql`, `)}) then ${issues.id} end)::int`,
148	    })
149	    .from(issues)
150	    .where(and(eq(issues.companyId, companyId), isNull(issues.hiddenAt)));
151	
152	  const commentConditions = [
153	    eq(issueComments.companyId, companyId),
154	    eq(issueComments.authorUserId, userId),
155	  ];
156	  if (from) commentConditions.push(gte(issueComments.createdAt, from));
157	  const [commentStats] = await db
158	    .select({ count: sql<number>`count(*)::int` })
159	    .from(issueComments)
160	    .where(and(...commentConditions));
161	
162	  const activityConditions = [
163	    eq(activityLog.companyId, companyId),
164	    eq(activityLog.actorType, "user"),
165	    eq(activityLog.actorId, userId),
166	  ];
167	  if (from) activityConditions.push(gte(activityLog.createdAt, from));
168	  const [activityStats] = await db
169	    .select({ count: sql<number>`count(*)::int` })
170	    .from(activityLog)
171	    .where(and(...activityConditions));
172	
173	  const costConditions = [
174	    eq(costEvents.companyId, companyId),
175	    userIssueInvolvementSql(companyId, userId),
176	  ];
177	  if (from) costConditions.push(gte(costEvents.occurredAt, from));
178	  const [costStats] = await db
179	    .select({
180	      costCents: sumNumber(costEvents.costCents),
181	      inputTokens: sumNumber(costEvents.inputTokens),
182	      cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
183	      outputTokens: sumNumber(costEvents.outputTokens),
184	      costEventCount: sql<number>`count(${costEvents.id})::int`,
185	    })
186	    .from(costEvents)
187	    .innerJoin(issues, and(eq(issues.id, costEvents.issueId), eq(issues.companyId, costEvents.companyId)))
188	    .where(and(...costConditions));
189	
190	  return {
191	    key,
192	    label,
193	    touchedIssues: Number(issueStats?.touchedIssues ?? 0),
194	    createdIssues: Number(issueStats?.createdIssues ?? 0),
195	    completedIssues: Number(issueStats?.completedIssues ?? 0),
196	    assignedOpenIssues: Number(issueStats?.assignedOpenIssues ?? 0),
197	    commentCount: Number(commentStats?.count ?? 0),
198	    activityCount: Number(activityStats?.count ?? 0),
199	    costCents: Number(costStats?.costCents ?? 0),
200	    inputTokens: Number(costStats?.inputTokens ?? 0),
201	    cachedInputTokens: Number(costStats?.cachedInputTokens ?? 0),
202	    outputTokens: Number(costStats?.outputTokens ?? 0),
203	    costEventCount: Number(costStats?.costEventCount ?? 0),
204	  };
205	}
