207	async function loadDailyStats(db: Db, companyId: string, userId: string): Promise<UserProfileDailyPoint[]> {
208	  const firstDay = startOfUtcDay(new Date(Date.now() - 13 * 24 * 60 * 60 * 1000));
209	  const points = new Map<string, UserProfileDailyPoint>();
210	  for (let index = 0; index < 14; index += 1) {
211	    const date = new Date(firstDay.getTime() + index * 24 * 60 * 60 * 1000);
212	    points.set(isoDay(date), {
213	      date: isoDay(date),
214	      activityCount: 0,
215	      completedIssues: 0,
216	      costCents: 0,
217	      inputTokens: 0,
218	      cachedInputTokens: 0,
219	      outputTokens: 0,
220	    });
221	  }
222	
223	  const activityDay = dayKeyExpr(sql`${activityLog.createdAt}`);
224	  const activityRows = await db
225	    .select({
226	      date: activityDay,
227	      count: sql<number>`count(*)::int`,
228	    })
229	    .from(activityLog)
230	    .where(
231	      and(
232	        eq(activityLog.companyId, companyId),
233	        eq(activityLog.actorType, "user"),
234	        eq(activityLog.actorId, userId),
235	        gte(activityLog.createdAt, firstDay),
236	      ),
237	    )
238	    .groupBy(activityDay);
239	
240	  for (const row of activityRows) {
241	    const point = points.get(row.date);
242	    if (point) point.activityCount = Number(row.count);
243	  }
244	
245	  const completedDay = dayKeyExpr(sql`${issues.completedAt}`);
246	  const completedRows = await db
247	    .select({
248	      date: completedDay,
249	      count: sql<number>`count(distinct ${issues.id})::int`,
250	    })
251	    .from(issues)
252	    .where(
253	      and(
254	        eq(issues.companyId, companyId),
255	        isNull(issues.hiddenAt),
256	        eq(issues.status, "done"),
257	        gte(issues.completedAt, firstDay),
258	        userIssueInvolvementSql(companyId, userId),
259	      ),
260	    )
261	    .groupBy(completedDay);
262	
263	  for (const row of completedRows) {
264	    const point = points.get(row.date);
265	    if (point) point.completedIssues = Number(row.count);
266	  }
267	
268	  const costDay = dayKeyExpr(sql`${costEvents.occurredAt}`);
269	  const costRows = await db
270	    .select({
271	      date: costDay,
272	      costCents: sumNumber(costEvents.costCents),
273	      inputTokens: sumNumber(costEvents.inputTokens),
274	      cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
275	      outputTokens: sumNumber(costEvents.outputTokens),
276	    })
277	    .from(costEvents)
278	    .innerJoin(issues, and(eq(issues.id, costEvents.issueId), eq(issues.companyId, costEvents.companyId)))
279	    .where(
280	      and(
281	        eq(costEvents.companyId, companyId),
282	        gte(costEvents.occurredAt, firstDay),
283	        userIssueInvolvementSql(companyId, userId),
284	      ),
285	    )
286	    .groupBy(costDay);
287	
288	  for (const row of costRows) {
289	    const point = points.get(row.date);
290	    if (!point) continue;
291	    point.costCents = Number(row.costCents);
292	    point.inputTokens = Number(row.inputTokens);
293	    point.cachedInputTokens = Number(row.cachedInputTokens);
294	    point.outputTokens = Number(row.outputTokens);
295	  }
296	
297	  return [...points.values()];
298	}
