300	export function userProfileRoutes(db: Db) {
301	  const router = Router();
302	
303	  router.get("/companies/:companyId/users/:userSlug/profile", async (req, res) => {
304	    const companyId = req.params.companyId as string;
305	    const userSlug = req.params.userSlug as string;
306	    assertCompanyAccess(req, companyId);
307	
308	    const row = await resolveCompanyUser(db, companyId, userSlug);
309	    if (!row) throw notFound("User not found");
310	    const canonicalSlug = userSlugCandidates(row)[0] ?? row.principalId;
311	    const userId = row.userId ?? row.principalId;
312	
313	    const [stats, daily, recentIssues, recentActivity, topAgents, topProviders] = await Promise.all([
314	      Promise.all(
315	        PROFILE_WINDOWS.map((entry) =>
316	          loadWindowStats(db, companyId, userId, entry.key, entry.label, windowStart(entry.days)),
317	        ),
318	      ),
319	      loadDailyStats(db, companyId, userId),
320	      db
321	        .select({
322	          id: issues.id,
323	          identifier: issues.identifier,
324	          title: issues.title,
325	          status: issues.status,
326	          priority: issues.priority,
327	          assigneeAgentId: issues.assigneeAgentId,
328	          assigneeUserId: issues.assigneeUserId,
329	          updatedAt: issues.updatedAt,
330	          completedAt: issues.completedAt,
331	        })
332	        .from(issues)
333	        .where(
334	          and(
335	            eq(issues.companyId, companyId),
336	            isNull(issues.hiddenAt),
337	            userIssueInvolvementSql(companyId, userId),
338	          ),
339	        )
340	        .orderBy(desc(issues.updatedAt))
341	        .limit(8),
342	      db
343	        .select({
344	          id: activityLog.id,
345	          action: activityLog.action,
346	          entityType: activityLog.entityType,
347	          entityId: activityLog.entityId,
348	          details: activityLog.details,
349	          createdAt: activityLog.createdAt,
350	        })
351	        .from(activityLog)
352	        .where(
353	          and(
354	            eq(activityLog.companyId, companyId),
355	            eq(activityLog.actorType, "user"),
356	            eq(activityLog.actorId, userId),
357	          ),
358	        )
359	        .orderBy(desc(activityLog.createdAt))
360	        .limit(12),
361	      db
362	        .select({
363	          agentId: costEvents.agentId,
364	          agentName: agents.name,
365	          costCents: sumNumber(costEvents.costCents),
366	          inputTokens: sumNumber(costEvents.inputTokens),
367	          cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
368	          outputTokens: sumNumber(costEvents.outputTokens),
369	        })
370	        .from(costEvents)
371	        .innerJoin(issues, and(eq(issues.id, costEvents.issueId), eq(issues.companyId, costEvents.companyId)))
372	        .leftJoin(agents, eq(agents.id, costEvents.agentId))
373	        .where(and(eq(costEvents.companyId, companyId), userIssueInvolvementSql(companyId, userId)))
374	        .groupBy(costEvents.agentId, agents.name)
375	        .orderBy(desc(sumNumber(costEvents.costCents)))
376	        .limit(5),
377	      db
378	        .select({
379	          provider: costEvents.provider,
380	          biller: costEvents.biller,
381	          model: costEvents.model,
382	          costCents: sumNumber(costEvents.costCents),
383	          inputTokens: sumNumber(costEvents.inputTokens),
384	          cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
385	          outputTokens: sumNumber(costEvents.outputTokens),
386	        })
387	        .from(costEvents)
388	        .innerJoin(issues, and(eq(issues.id, costEvents.issueId), eq(issues.companyId, costEvents.companyId)))
389	        .where(and(eq(costEvents.companyId, companyId), userIssueInvolvementSql(companyId, userId)))
390	        .groupBy(costEvents.provider, costEvents.biller, costEvents.model)
391	        .orderBy(desc(sumNumber(costEvents.costCents)))
392	        .limit(5),
393	    ]);
394	
395	    const user: UserProfileIdentity = {
396	      id: userId,
397	      slug: canonicalSlug,
398	      name: row.name,
399	      email: row.email,
400	      image: row.image,
401	      membershipRole: row.membershipRole,
402	      membershipStatus: row.status,
403	      joinedAt: row.createdAt,
404	    };
405	
406	    const payload: UserProfileResponse = {
407	      user,
408	      stats,
409	      daily,
410	      recentIssues: recentIssues.map((issue) => ({
411	        ...issue,
412	        status: issue.status as UserProfileResponse["recentIssues"][number]["status"],
413	        priority: issue.priority as UserProfileResponse["recentIssues"][number]["priority"],
414	      })),
415	      recentActivity,
416	      topAgents: topAgents.map((entry) => ({
417	        ...entry,
418	        costCents: Number(entry.costCents),
419	        inputTokens: Number(entry.inputTokens),
420	        cachedInputTokens: Number(entry.cachedInputTokens),
421	        outputTokens: Number(entry.outputTokens),
422	      })),
423	      topProviders: topProviders.map((entry) => ({
424	        ...entry,
425	        costCents: Number(entry.costCents),
426	        inputTokens: Number(entry.inputTokens),
427	        cachedInputTokens: Number(entry.cachedInputTokens),
428	        outputTokens: Number(entry.outputTokens),
429	      })),
430	    };
431	
432	    res.json(payload);
433	  });
434	
435	  return router;
436	}
